// launch-factory: 문의 접수 조립. 순서: 요청 제한(DB) → 멱등 키 → 입력 검사 → Turnstile → 저장 → 운영자 알림 → (선택) 접수 확인.
// 개인정보는 최소만 저장한다(이름 선택·연락처·내용). 보유 기간은 일반 30일, 불만·분쟁 3년(Cron 이 지난 것을 지운다).
// 접수 확인 메일과 첫 응답 약속은 lib/launch/support.ts(제품 설정)가 정한다.
// 운영자 메일(INQUIRY_OWNER_EMAIL)이 없으면 문의 창구만 꺼진다 — inquiryEnabled() 가 false 이고 서비스는 접수를 provider_unavailable 로 거절한다.
import { hitRateLimit } from "@launch-factory/db"
import { createInquiryService, type InquiryService } from "@launch-factory/inquiry"
import { createRateLimiter, ipAddressFromEnv, warnNoIpOnce } from "@launch-factory/security/rate-limit"
import { createTurnstile } from "@launch-factory/security/turnstile"
import { DEFAULT_LOCALE, PRODUCT_NAME } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { env, optional, required } from "@/lib/launch/env"
import { mailer } from "@/lib/launch/mailer"
import { SUPPORT } from "@/lib/launch/support"

let cached: Promise<InquiryService> | undefined

export function inquiry(): Promise<InquiryService> {
  return (cached ??= build())
}

/**
 * 문의 알림을 받을 운영자 메일. **없으면 문의 창구만 꺼진다**(사이트는 켜진다 — 운영자 결정 2026-10-05, 미리보기 전 쪽 500 사고).
 * 있으면 켜지 않는 척 속이지 않고 형식을 본다(live-env.ts 가 켜질 때 z.email() 로 확인). mock 은 없으면 가짜 주소로 켠다 —
 * 메일은 콘솔에만 찍히므로 어디로도 나가지 않는다. LF_BUSINESS_EMAIL 로 대신하지 않는다: 그것은 바닥글에 공개하는 표시 주소이지 개인정보가 오는 창구가 아니다.
 */
export function inquiryOwnerEmail(): string | undefined {
  const set = optional("INQUIRY_OWNER_EMAIL")
  return set ?? (env().LF_MODE === "live" ? undefined : "owner@example.test")
}

/** 문의를 받는가. 쪽(/contact)이 폼 대신 안내를 그리고, 배포 확인이 경고를 낼 때 읽는다. 데이터베이스에 닿지 않는다 */
export const inquiryEnabled = (): boolean => inquiryOwnerEmail() !== undefined

async function build(): Promise<InquiryService> {
  const db = await database()
  const live = env().LF_MODE === "live"
  const ownerAddress = inquiryOwnerEmail()
  return createInquiryService({
    db,
    mailer: mailer(),
    // 믿을 IP 머리는 환경이 정한다(대장 D205). 인증 항목·보안 항목과 같은 함수라 같은 사람을 같은 IP 로 센다
    limiter: createRateLimiter({ store: { hit: (key, windowMs, now) => hitRateLimit(db, key, windowMs, now) }, ipAddress: ipAddressFromEnv(process.env), onNoIp: warnNoIpOnce() }),
    turnstile: createTurnstile(live ? { mode: "live", secretKey: required("TURNSTILE_SECRET_KEY") } : { mode: "mock" }),
    // 주소가 없으면 owner 를 빼 접수만 끈다: 접수는 provider_unavailable 로 거절하고, 파기 Cron·종류 변경은 그대로 된다
    ...(ownerAddress ? { owner: { email: ownerAddress, locale: DEFAULT_LOCALE } } : {}),
    productName: PRODUCT_NAME,
    receipt: SUPPORT.receipt,
    ...(SUPPORT.responseTime ? { responseTime: SUPPORT.responseTime } : {}),
  })
}

// launch-factory: 고객 지원 설정(K05·K06·K10). 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
// 문의 화면(/contact)과 접수 확인 메일이 이 값을 그대로 읽는다. 값은 제품이 정한다 — 공장 코드에는 실제 주소·시간을 넣지 않는다.
export const SUPPORT = {
  /**
   * 첫 응답 약속. 문의 화면과 접수 확인 메일에 같은 글로 실린다. **지킬 수 있는 시간만 적는다**(전자상거래법 §21①3 — 응답 담당이 없는데 약속하지 않는다).
   * null 이면 약속 줄을 싣지 않는다. 화면 언어(영어)와 같은 말로 적는다.
   */
  responseTime: "1 business day" as string | null,
  /** 접수 확인 메일을 보낼지(연락처가 이메일일 때만). 방문자가 적은 주소로 나가므로 요청 제한·Turnstile 이 남용을 막는 장치다 */
  receipt: true,
  /** 사람이 직접 읽는 문의 메일 주소(선택). null 이면 화면에 주소를 싣지 않는다 — 폼이 문의 창구다 */
  email: null as string | null,
}

// launch-factory: 문의 접수 경로(POST, FormData 또는 JSON). 429 + Retry-After · 봇 400 · 칸 오류 400 · 확인 불가 503 · 처리 중 409.
// 폼에 숨은 입력 둘을 더한다: Turnstile 토큰 `cf-turnstile-response`, 폼을 열 때 만든 `idempotencyKey`.
import { inquiry } from "@/lib/launch/inquiry"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function POST(request: Request) {
  return (await inquiry()).handler(request)
}

// launch-factory: 문의 파기 Cron(하루 한 번 권장). 보유 기간이 지난 문의를 지운다.
// vercel.json 에 `{ "crons": [{ "path": "/api/cron/inquiry", "schedule": "0 4 * * *" }] }` 를 더한다. CRON_SECRET 이 없으면 401 이다.
import { cronAuthorized, unauthorized } from "@/lib/launch/cron"
import { inquiry } from "@/lib/launch/inquiry"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  if (!cronAuthorized(request)) return unauthorized()
  return Response.json({ purged: await (await inquiry()).purgeExpired() })
}

"use server"
// launch-factory: 문의 서버 액션 — web-factory contact-form 블록의 submit 포트 모양이다(`(input: Record<string, string>) => Promise<ActionResult>`).
// IP 는 요청 머리에서 읽어 요청 제한 키에만 쓴다(저장하지 않는다).
import { headers } from "next/headers"
import { inquiry } from "@/lib/launch/inquiry"

export async function submitInquiry(input: Record<string, string>) {
  return (await inquiry()).action({ headers: new Headers(await headers()) })(input)
}

"use server"
// launch-factory: 문의 종류 변경 서버 액션(운영자·관리자용). 누가 바꾸는지는 세션에서 읽은 사용자 행으로 정한다 — 입력의 isOwner·role·userId 는 읽지 않는다(대장 D170).
//   소유자 = 확인된 이메일이 INQUIRY_OWNER_EMAIL 과 같은 사람, 관리자 = user.role 에 admin 이 든 사람(Better Auth admin 플러그인과 같은 규칙). 정지된 사람은 아니다.
//   INQUIRY_OWNER_EMAIL 이 없으면(문의 창구 꺼짐) 소유자가 없고 관리자만 바꿀 수 있다 — 이미 받은 문의의 보유 기간(불만 3년)은 창구가 꺼져도 지켜야 한다.
//   대리 로그인 세션은 소유자도 관리자도 아니다(관리자가 사용자 이름으로 문의 종류를 바꾸지 못한다). 불만·분쟁 등급을 넘나드는 변경은 관리자만이다(서비스가 판정).
import { user } from "@launch-factory/db"
import { messages } from "@launch-factory/i18n"
import { actorFromUser, type InquiryActor, type InquiryKind } from "@launch-factory/inquiry"
import { eq } from "drizzle-orm"
import { authPort } from "@/lib/launch/auth"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { inquiry, inquiryOwnerEmail } from "@/lib/launch/inquiry"

const signInRequired = () => ({ ok: false as const, formError: messages(DEFAULT_LOCALE).auth.signInRequired })
const impersonationBlocked = () => ({ ok: false as const, status: 403 as const, code: "impersonation_blocked" as const, formError: messages(DEFAULT_LOCALE).auth.impersonationBlocked })
const invalidInput = { ok: false as const, error: "invalid_input" as const }

/** 지금 로그인한 사람의 행위자. 로그아웃·정지 → null(로그인 요구), 대리 세션 → "impersonated" */
async function actor(): Promise<InquiryActor | "impersonated" | null> {
  const s = await (await authPort()).session()
  if (!s.ok || !s.data) return null
  if (s.data.impersonatedBy) return "impersonated"
  const [row] = await (await database()).select({ id: user.id, role: user.role, email: user.email, emailVerified: user.emailVerified, banned: user.banned }).from(user).where(eq(user.id, s.data.userId)).limit(1)
  // 운영자 메일이 없으면(문의 창구가 꺼진 상태) 「소유자」는 아무도 아니다 — 관리자 역할은 그대로 판정한다. 지난 문의의 보유 기간을 바꾸는 일은 창구와 별개다
  return row ? actorFromUser(row, inquiryOwnerEmail() ?? "") : null
}

const text = (v: unknown, max: number): string | null => (typeof v === "string" && v.trim() !== "" && v.length <= max ? v.trim() : null)

/** 입력: { reference, reason? }(+ to). 모양이 틀리면 invalid_input — 서비스는 부르지 않는다 */
function parse(input: unknown, needsKind: boolean): { reference: string; to: string; reason?: string } | null {
  if (typeof input !== "object" || input === null) return null
  const i = input as Record<string, unknown>
  const reference = text(i.reference, 64)
  const to = needsKind ? text(i.to, 32) : "complaint"
  if (!reference || !to) return null
  if (i.reason === undefined) return { reference, to }
  const reason = text(i.reason, 500)
  return reason ? { reference, to, reason } : null
}

/** 문의 종류를 바꾼다(접수 번호 reference, 새 종류 to). 보유 기간이 접수일 기준으로 다시 정해지고 admin_actions 에 한 줄이 남는다 */
export async function reclassifyInquiry(input: unknown) {
  const p = parse(input, true)
  if (!p) return invalidInput
  const who = await actor()
  if (who === "impersonated") return impersonationBlocked()
  if (!who) return signInRequired()
  return (await inquiry()).reclassify(p.reference, p.to as InquiryKind, who, p.reason ? { reason: p.reason } : {})
}

/** 불만 문의로 올린다(관리자만 — 서비스가 판정) */
export async function markInquiryAsComplaint(input: unknown) {
  const p = parse(input, false)
  if (!p) return invalidInput
  const who = await actor()
  if (who === "impersonated") return impersonationBlocked()
  if (!who) return signInRequired()
  return (await inquiry()).markAsComplaint(p.reference, who, p.reason ? { reason: p.reason } : {})
}

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

export function database(): Promise<Database> {
  return (cached ??= env().LF_MODE === "mock" ? db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }) : Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}

// launch-factory: Cron 경로 인증. Vercel Cron 은 CRON_SECRET 이 있으면 `Authorization: Bearer <값>` 을 붙여 부른다
// (https://vercel.com/docs/cron-jobs/manage-cron-jobs#securing-cron-jobs). 값이 없거나 다르면 거절한다 — 비밀이 없으면 열어 두지 않는다.
import { timingSafeEqual } from "node:crypto"

export function cronAuthorized(request: Request): boolean {
  const secret = process.env.CRON_SECRET
  if (!secret) return false
  const given = request.headers.get("authorization") ?? ""
  const want = `Bearer ${secret}`
  return given.length === want.length && timingSafeEqual(Buffer.from(given), Buffer.from(want))
}

export const unauthorized = () => Response.json({ error: "unauthorized" }, { status: 401 })

// launch-factory: 마이그레이션 적용. 사용법: DATABASE_URL=<직접 연결(5432)> node db/migrate.mjs
// 이 폴더의 migrations/ 를 순서대로 적용한다. 이미 적용한 파일은 건너뛴다(drizzle 기록 표).
import { fileURLToPath } from "node:url"
import postgres from "postgres"
import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"

const url = process.env.DATABASE_URL
if (!url) {
  console.error("DATABASE_URL is not set")
  process.exit(1)
}
if (new URL(url).port === "6543") {
  console.error("Use the direct connection (port 5432) for migrations, not the transaction pooler (6543).")
  process.exit(1)
}

const client = postgres(url, { max: 1 })
try {
  await migrate(drizzle(client), { migrationsFolder: fileURLToPath(new URL("./migrations", import.meta.url)) })
  console.log("migrations applied")
} finally {
  await client.end()
}

// 문의(v0 Task 15, 대장 D97 — 운영자 판정 2026-09-30 02:46 「v0로 앞당김」)와 폼 제출 멱등 키(D105).
// - inquiries: 문의 한 건. 개인정보는 최소만 — 이름(선택)·연락처(이메일 또는 전화)·문의 내용. IP·브라우저 정보는 저장하지 않는다.
//   보유 기간이 지나면(expires_at) purgeExpiredInquiries 가 지운다(개인정보 보호법 제21조① — 불필요해지면 지체 없이 파기).
//   기본 30일(D97). kind 가 complaint·dispute 인 문의는 소비자 불만·분쟁 처리 기록이라 전자상거래법 시행령 제6조①4에 따라 3년(D134).
//   kind 가 바뀌면 expires_at 도 접수일(created_at) 기준으로 다시 계산한다 — 바꾼 내역은 admin_actions 에 한 줄씩 남는다.
// - idempotency_keys: 폼을 열 때 만든 키 → 첫 성공 결과. 같은 키로 다시 보내면 24시간 동안 같은 결과를 돌려준다(Stripe 방식).
//   result 가 null 이면 처리 중이다. 실패한 제출은 남기지 않는다(고친 뒤 같은 키로 다시 보낼 수 있게).
// 시각은 앱이 넣는다(DB 기본값 now() 에 기대지 않는다 — Task 4 D26 규칙).
import { sql } from "drizzle-orm"
import { check, index, jsonb, pgTable, primaryKey, text, timestamp, uuid } from "drizzle-orm/pg-core"
import { user } from "./auth-base.ts"

const tz = { withTimezone: true } as const

/** 문의 종류(D134 — 운영자 판정 2026-09-30 03:35). complaint·dispute 는 소비자 불만·분쟁 처리 기록이라 3년, 나머지는 30일 */
export const INQUIRY_KINDS = ["general", "consultation", "quote", "complaint", "dispute"] as const
export type InquiryKind = (typeof INQUIRY_KINDS)[number]

export const inquiries = pgTable(
  "inquiries",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** 사람에게 보이는 접수 번호(예: Q-7K3M9P2A) */
    reference: text("reference").notNull().unique(),
    /** 어느 폼에서 왔는지(블록 id 등, 개인정보 아님) */
    form: text("form").notNull(),
    name: text("name"),
    contact: text("contact").notNull(),
    contactKind: text("contact_kind").$type<"email" | "phone">().notNull(),
    message: text("message").notNull(),
    kind: text("kind").$type<InquiryKind>().notNull().default("general"),
    locale: text("locale").notNull(),
    /** 로그인한 채 보냈으면 그 사용자. 탈퇴하면 연결만 끊는다(문의 자체는 보유 기간까지) */
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at", tz).notNull(),
    expiresAt: timestamp("expires_at", tz).notNull(),
    ownerNotifiedAt: timestamp("owner_notified_at", tz),
    receiptSentAt: timestamp("receipt_sent_at", tz),
  },
  (t) => [
    index("inquiries_expires_at_idx").on(t.expiresAt),
    check("inquiries_kind_check", sql`${t.kind} in ('general', 'consultation', 'quote', 'complaint', 'dispute')`),
  ],
)

export const idempotencyKeys = pgTable(
  "idempotency_keys",
  {
    /** 어느 제출인지(예: "inquiry", "checkout") — 같은 키라도 범위가 다르면 다른 요청이다 */
    scope: text("scope").notNull(),
    key: text("key").notNull(),
    result: jsonb("result"),
    createdAt: timestamp("created_at", tz).notNull(),
  },
  (t) => [primaryKey({ columns: [t.scope, t.key] }), index("idempotency_keys_created_at_idx").on(t.createdAt)],
)

-- 접속기록 위·변조 방지(「개인정보의 안전성 확보조치 기준」 제8조제3항). access_logs는 추가 전용이다.
--   UPDATE·TRUNCATE: 항상 거부
--   DELETE: 접속일시가 1년(제8조제1항 최소 보관 기간)을 넘은 행만 허용 — 파기 작업이 2년 설정이면 그보다 늦게 지운다
-- 트리거는 역할과 상관없이 걸린다(표 소유자가 트리거를 끄는 것까지는 막지 못한다 — 해시 사슬은 다음 단계, docs/qa/task-3-report.md).
